1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	const BASE_SPHINX_SCORE = 2;
8	const TYPES_FOR_BASE_SCORE = 3;
9	
10	/**
11	 * A card's monster type ignores its rank: Undead Warrior (1) and
12	 * Undead Warrior (3) are the same type.
13	 */
14	const distinctMonsterTypes = (army: Card[]): Set<string> =>
15	  new Set(army.map((card) => card.monster));
16	
17	/**
18	 * Beyond three distinct types the Sphinx scores on a steeper curve.
19	 * Fitted to the examples so far (5 types → 3, 6 types → 5); no example
20	 * yet pins down 4 types, where this formula happens to dip below the base.
21	 */
22	const bonusScoreFor = (typeCount: number): number =>
23	  (typeCount - TYPES_FOR_BASE_SCORE) * 2 - 1;
24	
25	export const scoreArmy = (army: Card[]): number => {
26	  const types = distinctMonsterTypes(army);
27	  if (!types.has(SPHINX)) return 0;
28	  if (types.size <= TYPES_FOR_BASE_SCORE) return BASE_SPHINX_SCORE;
29	  return bonusScoreFor(types.size);
30	};
